from support import Client,sql
import pathlib,json,time,statistics,uuid
DB='clubs_governance_scale'
c=Client();c.login('admin@example.test');w=next(x for x in c.req('/workspaces')[1] if x['role']=='Association Super Admin' and x['association'].startswith('Global'));c.activate(w);tag=uuid.uuid4().hex[:8]
print('Preparing 10,000 dated events across clubs...',flush=True)
sql(f'''BEGIN;SET LOCAL statement_timeout='300s';DELETE FROM "Events" WHERE "Title" LIKE 'Calendar scale %';INSERT INTO "Events" SELECT(jsonb_populate_record(NULL::"Events",to_jsonb(e)||jsonb_build_object('Id',md5('calendar-{tag}-'||o."Id"||g.n)::uuid,'OrgId',o."Id",'Title','Calendar scale {tag} '||o."Code",'StartsAt',now()+((row_number()over(order by o."Id"))%60)*interval '1 day','EndsAt',now()+((row_number()over(order by o."Id"))%60)*interval '1 day'+interval '4 hours','RegistrationStartsAt',now()-interval '1 day','RegistrationEndsAt',now()+((row_number()over(order by o."Id"))%60)*interval '1 day'+interval '2 hours','RsvpDeadline',now()+((row_number()over(order by o."Id"))%60)*interval '1 day','ReminderAt',NULL,'Lifecycle','Scheduled'))).* FROM "Orgs" o CROSS JOIN generate_series(1,2) g(n) CROSS JOIN(SELECT * FROM "Events" WHERE "TenantId"='{w['tenantId']}' LIMIT 1)e JOIN "Levels" l ON l."Id"=o."LevelId" WHERE o."TenantId"=e."TenantId" AND l."IsClub" LIMIT 10000; ANALYZE "Events";COMMIT;''',DB)
values=[]
for i in range(101):
 begin=time.perf_counter();code,b=c.req('/events?size=30');assert code==200,(code,b)
 if i:values.append((time.perf_counter()-begin)*1000)
values.sort();q=f'''SELECT "Id","Title","StartsAt" FROM "Events" WHERE "TenantId"='{w['tenantId']}' AND "StartsAt">now()-interval '1 month' AND "StartsAt"<now()+interval '2 months' ORDER BY "StartsAt","Id" LIMIT 30''';plan=json.loads(sql('EXPLAIN(ANALYZE,BUFFERS,TIMING OFF,FORMAT JSON) '+q,DB));report={'event_rows':int(sql('SELECT count(*) FROM "Events"',DB)),'samples':100,'p50_ms':statistics.median(values),'p95_ms':values[94],'p99_ms':values[98],'errors':0,'plan':plan,'conditions':'10,000 additional synthetic events across the large club hierarchy. Warm sequential loopback HTTP, 100 samples after one warmup. No concurrent user load in this calendar read measurement.'};pathlib.Path('test-results/phase4-calendar-scale.json').write_text(json.dumps(report,indent=2));print(json.dumps({k:v for k,v in report.items() if k!='plan'},indent=2))
